Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "encoding": {
    "x": {
      "field": "Mês",
      "type": "temporal",
      "timeUnit": "yearmonth",
      "title": null,
      "axis": {
        "format": "%Y",
        "tickCount": "year",
        "labelAlign": "left",
        "labelPadding": 6,
        "labelOverlap": "greedy"
      }
    }
  },
  "layer": [
    {
      "transform": [
        {
          "filter": "isValid(datum[''Marco legal'']) && datum[''Marco legal''] != ''''"
        },
        {
          "window": [
            {
              "op": "row_number",
              "as": "i"
            }
          ]
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "rule",
            "color": "#C8C6C4",
            "strokeDash": [
              3,
              3
            ]
          }
        },
        {
          "transform": [
            {
              "filter": "datum.i % 3 == 0"
            }
          ],
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "dx": 4,
            "y": 28,
            "fontSize": 9,
            "color": "#605E5C",
            "limit": 130
          },
          "encoding": {
            "text": {
              "field": "Marco legal"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "datum.i % 3 == 1"
            }
          ],
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "dx": 4,
            "y": 4,
            "fontSize": 9,
            "color": "#605E5C",
            "limit": 130
          },
          "encoding": {
            "text": {
              "field": "Marco legal"
            }
          }
        },
        {
          "transform": [
            {
              "filter": "datum.i % 3 == 2"
            }
          ],
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "dx": 4,
            "y": 16,
            "fontSize": 9,
            "color": "#605E5C",
            "limit": 130
          },
          "encoding": {
            "text": {
              "field": "Marco legal"
            }
          }
        }
      ]
    },
    {
      "transform": [
        {
          "fold": [
            "Custo elétrico",
            "Custo gasolina",
            "Custo etanol"
          ],
          "as": [
            "serie",
            "valor"
          ]
        },
        {
          "filter": "isValid(datum.valor)"
        },
        {
          "calculate": "datum.serie == ''Custo elétrico'' ? ''Elétrico'' : datum.serie == ''Custo gasolina'' ? ''Gasolina'' : datum.serie == ''Custo etanol'' ? ''Etanol'' : ''''",
          "as": "Energia"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "line",
            "interpolate": "monotone"
          },
          "encoding": {
            "y": {
              "field": "valor",
              "type": "quantitative",
              "title": "R$ por 100 km",
              "axis": {
                "format": "$,.0f",
                "tickCount": 5
              }
            },
            "color": {
              "field": "Energia",
              "type": "nominal",
              "scale": {
                "domain": [
                  "Elétrico",
                  "Gasolina",
                  "Etanol"
                ],
                "range": [
                  "#E0B000",
                  "#191919",
                  "#A19F9D"
                ]
              },
              "legend": {
                "orient": "top",
                "title": null,
                "direction": "horizontal"
              }
            },
            "strokeWidth": {
              "condition": {
                "test": "datum.Energia == ''Elétrico''",
                "value": 3
              },
              "value": 2
            }
          }
        },
        {
          "mark": {
            "type": "circle",
            "size": 50,
            "opacity": 0.01
          },
          "encoding": {
            "y": {
              "field": "valor",
              "type": "quantitative"
            },
            "tooltip": [
              {
                "field": "Mês",
                "type": "temporal",
                "timeUnit": "yearmonth",
                "title": "Mês",
                "format": "%b/%Y"
              },
              {
                "field": "Custo elétrico",
                "title": "Elétrico (R$/100 km)",
                "format": "$,.2f"
              },
              {
                "field": "Custo gasolina",
                "title": "Gasolina (R$/100 km)",
                "format": "$,.2f"
              },
              {
                "field": "Custo etanol",
                "title": "Etanol (R$/100 km)",
                "format": "$,.2f"
              },
              {
                "field": "Preço eletricidade",
                "title": "Eletricidade (R$/kWh)",
                "format": "$,.3f"
              },
              {
                "field": "Preço gasolina",
                "title": "Gasolina (R$/l)",
                "format": "$,.2f"
              },
              {
                "field": "Preço etanol",
                "title": "Etanol (R$/l)",
                "format": "$,.2f"
              }
            ]
          }
        }
      ]
    }
  ]
}'
